import { useMemo, useState } from 'react';
import { EmptyState, LoadingState } from '@/components/molecules';
import { cn } from '@/lib/cn';

/**
 * DataTable — an ORGANISM, not a molecule: it is a distinct section of UI that
 * composes molecules (the empty and loading states) and owns sorting state.
 * That is why this registry item targets `@components/organisms/`.
 *
 * Deliberately dependency-free. A headless table library is the right call once
 * you need column resizing, virtualisation or grouping; until then it is a large
 * dependency for sorting an array.
 */

export interface Column<T> {
  /** Stable id, also used as the sort key. */
  id: string;
  header: string;
  /** Cell renderer. Keep it presentational. */
  cell: (row: T) => React.ReactNode;
  /** Value used for sorting. Omit to make the column unsortable. */
  sortValue?: (row: T) => string | number;
  align?: 'left' | 'right';
}

export interface DataTableProps<T> {
  rows: readonly T[];
  columns: readonly Column<T>[];
  rowKey: (row: T) => string;
  caption: string;
  isLoading?: boolean;
  emptyTitle?: string;
  className?: string;
}

type SortState = { columnId: string; direction: 'asc' | 'desc' } | null;

export function DataTable<T>({
  rows,
  columns,
  rowKey,
  caption,
  isLoading = false,
  emptyTitle,
  className,
}: DataTableProps<T>) {
  const [sort, setSort] = useState<SortState>(null);

  const sorted = useMemo(() => {
    if (!sort) return rows;
    const column = columns.find((c) => c.id === sort.columnId);
    if (!column?.sortValue) return rows;

    const factor = sort.direction === 'asc' ? 1 : -1;
    return [...rows].sort((a, b) => {
      const left = column.sortValue?.(a) ?? '';
      const right = column.sortValue?.(b) ?? '';
      if (typeof left === 'number' && typeof right === 'number') return (left - right) * factor;
      return String(left).localeCompare(String(right)) * factor;
    });
  }, [rows, columns, sort]);

  function toggle(columnId: string) {
    setSort((current) =>
      current?.columnId === columnId
        ? { columnId, direction: current.direction === 'asc' ? 'desc' : 'asc' }
        : { columnId, direction: 'asc' },
    );
  }

  // All four states, as AGENTS.md requires.
  if (isLoading) return <LoadingState rows={5} />;
  // exactOptionalPropertyTypes: omit the prop rather than pass `undefined`.
  if (rows.length === 0)
    return <EmptyState {...(emptyTitle === undefined ? {} : { title: emptyTitle })} />;

  return (
    <div className={cn('overflow-x-auto rounded-lg border border-border bg-card', className)}>
      <table className="w-full text-sm">
        <caption className="sr-only">{caption}</caption>
        <thead>
          <tr className="border-b border-border">
            {columns.map((column) => {
              const active = sort?.columnId === column.id;
              const sortable = column.sortValue !== undefined;
              return (
                <th
                  key={column.id}
                  scope="col"
                  // aria-sort is what tells a screen reader the table is sorted.
                  aria-sort={
                    active ? (sort.direction === 'asc' ? 'ascending' : 'descending') : 'none'
                  }
                  className={cn(
                    'px-4 py-3 font-medium text-muted-foreground',
                    column.align === 'right' ? 'text-right' : 'text-left',
                  )}
                >
                  {sortable ? (
                    <button
                      type="button"
                      onClick={() => toggle(column.id)}
                      className="inline-flex items-center gap-1 rounded-sm hover:text-foreground"
                    >
                      {column.header}
                      <span aria-hidden="true" className="text-xs">
                        {active ? (sort.direction === 'asc' ? '↑' : '↓') : '↕'}
                      </span>
                    </button>
                  ) : (
                    column.header
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {sorted.map((row) => (
            <tr key={rowKey(row)} className="border-b border-border/50 last:border-0">
              {columns.map((column) => (
                <td
                  key={column.id}
                  className={cn(
                    'px-4 py-3 text-card-foreground',
                    column.align === 'right' ? 'text-right tabular-nums' : 'text-left',
                  )}
                >
                  {column.cell(row)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import type { Meta, StoryObj } from '@storybook/react-vite';
import { DataTable, type Column } from '@/components/organisms/data-table';

interface Order {
  id: string;
  customer: string;
  total: number;
}

const rows: Order[] = [
  { id: 'A-1001', customer: 'Acme Corp', total: 2400 },
  { id: 'A-1002', customer: 'Globex', total: 980 },
  { id: 'A-1003', customer: 'Initech', total: 15600 },
];

const columns: Column<Order>[] = [
  { id: 'id', header: 'Order', cell: (r) => r.id, sortValue: (r) => r.id },
  { id: 'customer', header: 'Customer', cell: (r) => r.customer, sortValue: (r) => r.customer },
  {
    id: 'total',
    header: 'Total',
    cell: (r) => `$${r.total.toLocaleString()}`,
    sortValue: (r) => r.total,
    align: 'right',
  },
];

const meta = {
  title: 'Organisms/DataTable',
  component: DataTable,
  tags: ['autodocs'],
  args: { rows, columns, rowKey: (r: Order) => r.id, caption: 'Recent orders' },
} satisfies Meta<typeof DataTable<Order>>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {};
export const Loading: Story = { args: { isLoading: true } };
export const Empty: Story = { args: { rows: [] } };
/* Long content is where tables actually break. */
export const LongContent: Story = {
  args: {
    rows: [{ id: 'A-1004', customer: 'ü'.repeat(70), total: 99999999 }],
  },
};

import { describe, expect, it } from 'vitest';
import { render, screen, userEvent, within } from '@/testing/render';
import { DataTable, type Column } from '@/components/organisms/data-table';

interface Row {
  id: string;
  name: string;
  total: number;
}

const rows: Row[] = [
  { id: '1', name: 'Beta', total: 30 },
  { id: '2', name: 'Alpha', total: 10 },
  { id: '3', name: 'Gamma', total: 20 },
];

const columns: Column<Row>[] = [
  { id: 'name', header: 'Name', cell: (r) => r.name, sortValue: (r) => r.name },
  { id: 'total', header: 'Total', cell: (r) => r.total, sortValue: (r) => r.total, align: 'right' },
];

/**
 * Values of one column, body rows only.
 *
 * `within(row).getAllByRole('cell')` rather than `row.cells`: getAllByRole
 * returns HTMLElement, which has no `.cells`, so the latter is an implicit any.
 */
function column(index: number): (string | null)[] {
  return screen
    .getAllByRole('row')
    .slice(1)
    .map((row) => within(row).getAllByRole('cell')[index]?.textContent ?? null);
}

describe('DataTable', () => {
  it('renders rows with an accessible caption', () => {
    render(<DataTable rows={rows} columns={columns} rowKey={(r) => r.id} caption="Orders" />);
    expect(screen.getByRole('table', { name: 'Orders' })).toBeInTheDocument();
    expect(column(0)).toEqual(['Beta', 'Alpha', 'Gamma']);
  });

  it('sorts ascending then descending, and reports it via aria-sort', async () => {
    render(<DataTable rows={rows} columns={columns} rowKey={(r) => r.id} caption="Orders" />);

    await userEvent.click(screen.getByRole('button', { name: /Name/ }));
    expect(column(0)).toEqual(['Alpha', 'Beta', 'Gamma']);
    expect(screen.getByRole('columnheader', { name: /Name/ })).toHaveAttribute(
      'aria-sort',
      'ascending',
    );

    await userEvent.click(screen.getByRole('button', { name: /Name/ }));
    expect(column(0)).toEqual(['Gamma', 'Beta', 'Alpha']);
    expect(screen.getByRole('columnheader', { name: /Name/ })).toHaveAttribute(
      'aria-sort',
      'descending',
    );
  });

  it('sorts numbers numerically, not lexically', async () => {
    const wide = [...rows, { id: '4', name: 'Delta', total: 100 }];
    render(<DataTable rows={wide} columns={columns} rowKey={(r) => r.id} caption="Orders" />);

    await userEvent.click(screen.getByRole('button', { name: /Total/ }));
    expect(column(1)).toEqual(['10', '20', '30', '100']);
  });

  it('shows the empty state instead of an empty table', () => {
    render(<DataTable rows={[]} columns={columns} rowKey={(r) => r.id} caption="Orders" />);
    expect(screen.queryByRole('table')).not.toBeInTheDocument();
    expect(screen.getByRole('heading')).toBeInTheDocument();
  });

  it('shows the loading state', () => {
    render(
      <DataTable rows={[]} columns={columns} rowKey={(r) => r.id} caption="Orders" isLoading />,
    );
    expect(screen.getByRole('status')).toBeInTheDocument();
  });
});
